entries[16055] = { ["name"] = "Black Nightsaber", ["text"] = "1.5 sec cast\nSummons and dismisses a rideable Black Nightsaber.\n\"Considered one of Azeroth's perfect predators, these agile beasts can sprint through dense forests without making a sound.\"\nLegacy" }
entries[16056] = { ["name"] = "Ancient Frostsaber", ["text"] = "1.5 sec cast\nSummons and dismisses a rideable Ancient Frostsaber.\n\"The lack of spots or stripes marks this beast as a descendant of the most ancient frostsaber line.\"\nLegacy" }
entries[16057] = { ["name"] = "Place Unforged Seal", ["text"] = "5 yd range\n0.5 sec cast\nPlaces the Unforged Seal of Ascension. Use in front of Emberstrife." }
entries[16058] = { ["name"] = "Primal Leopard", ["text"] = "1.5 sec cast\nSummons and dismisses a rideable Primal Leopard." }
entries[16059] = { ["name"] = "Tawny Sabercat", ["text"] = "1.5 sec cast\nSummons and dismisses a rideable Tawny Sabercat." }
entries[16060] = { ["name"] = "Golden Sabercat", ["text"] = "1.5 sec cast\nSummons and dismisses a rideable Golden Sabercat." }
