entries[16069] = { ["name"] = "Nefarius Attack 001" }
entries[16070] = { ["name"] = "Nefarius Attack 000", ["text"] = "60 yd range\nInstant\nLaunches an Arcane Missile at the enemy, causing 1 Arcane damage." }
entries[16071] = { ["name"] = "Curse of the Firebrand", ["text"] = "30 yd range\n2 sec cast\nInflicts 50 Fire damage to an enemy every 6 sec. for 30 sec." }
entries[16072] = { ["name"] = "Purify and Place Food", ["text"] = "Melee Range\n5 sec cast\nReagents:\nBlackwood Fruit Sample , Blackwood Grain Sample , Blackwood Nut Sample\nCreates a bowl of purified food that the furbolg are sure to enjoy. It requires fruit, grain, and nuts from the Blackwood camp." }
entries[16073] = { ["name"] = "Filling", ["text"] = "5 yd range\n3 sec cast\nFill with moonwell water to prepare the bowl to cleanse food placed in it." }
entries[16074] = { ["name"] = "Burning Felguard Spawn" }
entries[16075] = { ["name"] = "Throw Axe", ["text"] = "40 yd range\n1 sec cast\nHurls a massive axe at a random enemy, dealing 1158 damage and stunning them for 2 sec." }
entries[16077] = { ["name"] = "Filling", ["text"] = "10 yd range\n4 sec cast\nTakes a sampling from the Cliffspring River." }
entries[16078] = { ["name"] = "Emberseer Despawn" }
entries[16079] = { ["name"] = "Fire Nova", ["text"] = "Instant\nInflicts Fire damage to nearby enemies." }
entries[16080] = { ["name"] = "Red Wolf", ["text"] = "1.5 sec cast\nSummons and dismisses a rideable Red Wolf.\n\"Almost none remain in the whole of Azeroth; only the most experienced will have seen one.\"\nLegacy" }
entries[16081] = { ["name"] = "Arctic Wolf", ["text"] = "1.5 sec cast\nSummons and dismisses a rideable Arctic Wolf.\n\"Once thought to be nearly extinct, this wolf can still occasionally be seen in the company of a few Horde veterans\"\nLegacy" }
entries[16082] = { ["name"] = "Palomino", ["text"] = "1.5 sec cast\nSummons and dismisses a rideable Palomino.\n\"Human nobles have long favored this majestic breed for its beautiful golden coat and flowing white mane.\"\nLegacy" }
entries[16083] = { ["name"] = "White Stallion", ["text"] = "1.5 sec cast\nSummons and dismisses a White Stallion.\n\"The powerful and unyielding white stallion features heavily in the myths of ancient human tribes.\"\nLegacy" }
